"""Fixed, symmetric 31-tap low-pass for the optional 16 -> 8 kHz music path."""
import numpy as np
from scipy.signal import firwin,freqz
from audit import ROOT,Run,write_json

if __name__=='__main__':
 r=Run('design_music_decimator');c=np.rint(firwin(31,3200,fs=16000,window='hamming')*32768).astype(int);c[15]+=32768-int(sum(c))
 cases='\n'.join(f"   5'd{i}:coefficient=16'sd{v};" if v>=0 else f"   5'd{i}:coefficient=-16'sd{-v};" for i,v in enumerate(c))
 source='''`timescale 1ns/1ps
// Generated by host/design_music_decimator.py. One serial DSP; full-rate front end is unchanged.
module music_decimator(input wire clk,reset,enable,input wire pcm_valid,
 input wire signed [15:0] pcm,input wire [63:0] pcm_index,
 output reg out_valid=0,output reg signed [15:0] out_pcm=0,output reg [63:0] out_index=0);
 reg signed [15:0] history[0:30];integer j;
 initial begin for(j=0;j<31;j=j+1)history[j]=0;end
 function automatic signed [15:0] coefficient(input [4:0] n);
  begin case(n)
COEFFICIENTS
   default:coefficient=0;
  endcase end
 endfunction
 reg phase=0,running=0,v0=0,v1=0,first0=0,last0=0,first1=0,last1=0;
 reg [4:0] tap=0;reg [63:0] active_index=0;
 reg signed [15:0] a=0,b=0;reg signed [31:0] product=0;
 reg signed [39:0] accumulator=0;
 wire signed [39:0] total=(first1 ? 40'sd0 : accumulator)+{{8{product[31]}},product};
 wire signed [39:0] rounded=total+(total[39] ? 40'sd16383 : 40'sd16384);
 wire signed [24:0] scaled=rounded>>>15;
 always @(posedge clk)begin
  out_valid<=0;
  if(reset)begin
   for(j=0;j<31;j=j+1)history[j]<=0;
  end else if(pcm_valid)begin
   history[0]<=pcm;for(j=1;j<31;j=j+1)history[j]<=history[j-1];
  end
  if(reset || !enable)begin phase<=0;running<=0;v0<=0;v1<=0;accumulator<=0;end
  else begin
   v0<=running;v1<=v0;first1<=first0;last1<=last0;product<=a*b;
   if(pcm_valid)begin
    phase<=!phase;
    if(!phase)begin running<=1;tap<=0;active_index<=pcm_index;end
   end
   if(running)begin
    a<=history[tap];b<=coefficient(tap);first0<=tap==0;last0<=tap==30;
    if(tap==30)running<=0;else tap<=tap+1'b1;
   end
   if(v1)begin
    accumulator<=total;
    if(last1)begin
     out_valid<=1;out_index<=active_index;
     if(scaled>32767)out_pcm<=32767;else if(scaled < -32768)out_pcm<=-32768;else out_pcm<=scaled[15:0];
    end
   end
  end
 end
endmodule
'''.replace('COEFFICIENTS',cases)
 (ROOT/'rtl/music_decimator.sv').write_text(source,encoding='ascii')
 hz,response=freqz(c/32768,worN=8192,fs=16000)
 result={'taps':31,'cutoff_hz':3200,'window':'Hamming','input_hz':16000,'output_hz':8000,'coefficients_q15':c.tolist(),'sum_q15':int(sum(c)),
   'gain_1k_dB':float(20*np.log10(abs(response[np.argmin(abs(hz-1000))]))),'gain_6k_dB':float(20*np.log10(abs(response[np.argmin(abs(hz-6000))]))),
   'group_delay_input_samples':15,'storage_note':'20秒8kHz仍是160000点；原16kHz前端与事件不改'}
 write_json(ROOT/'config/music_decimator.json',result);write_json(r.path/'design.json',result);r.manifest();print(result)
